package com.hirain.aiagent.rag.indexer.corpus;
import com.hirain.aiagent.rag.indexer.cli.CliCommandException; import com.hirain.aiagent.rag.indexer.cli.CliExitCode; import java.io.IOException; import java.nio.file.Files; import java.nio.file.Path;
/** 资源上限检查不读取正文，以保证拒绝发生在 Parser/第三方库加载前。 */
public final class CorpusSecurityValidator { public void validateFile(Path file,CorpusResourceBudget budget){try{if(Files.size(file)>budget.maxSingleFileBytes())throw new CliCommandException(CliExitCode.INPUT_OR_PARSE_ERROR,"SOURCE_SIZE_LIMIT_EXCEEDED");}catch(IOException e){throw new CliCommandException(CliExitCode.INPUT_OR_PARSE_ERROR,"SOURCE_PATH_OUTSIDE_CORPUS");}} public void validateHash(Path file,String expected){try{if(!com.hirain.aiagent.rag.indexer.util.Sha256.file(file).equals(expected))throw new CliCommandException(CliExitCode.INPUT_OR_PARSE_ERROR,"SOURCE_HASH_MISMATCH");}catch(CliCommandException e){throw e;}catch(Exception e){throw new CliCommandException(CliExitCode.INPUT_OR_PARSE_ERROR,"SOURCE_HASH_MISMATCH");}} }
